INSERT INTO `protocols` (id, name, parameters, bulk_modifier, description, observable, reportable, multiplier, double_params) VALUES
  (1, 'Dump resource', 1, 100, 'jettison(N, R), or perform(1, N, R): Dumps N units of resource R into space. N is required (1 for one unit). Burns 1 fuel.', 1, 1, 1, 0),
  (2, 'Burn power', 1, 100, 'perform(2, N): Burns N fuel to power the drone''s computer. The engine does this for every drone, 1 fuel per 200,000 instructions; a drone that can''t pay becomes a wreck.', 0, 0, 0, 0),
  (3, 'Wait', 1, 100, 'wait(M), or perform(3, M): Waits M game minutes (1 to 10,080: a week) doing nothing. The script pauses and runs no instructions until then, so waiting costs no fuel.', 1, 1, 0, 0),
  (7, 'Post sell order', 3, 100, 'sell_order(P, M, R), or perform(7, P, M, R): Places order to sell resource R at price P, keeping min M units at drone''s cargo hold. Burns 1 fuel.', 1, 1, 0, 0),
  (8, 'Post buy order', 3, 100, 'buy_order(P, M, R), or perform(8, P, M, R): Places order to buy resource R at price P, keeping max M units at drone''s cargo hold. Burns 1 fuel.', 1, 1, 0, 0),
  (10, 'Push resource', 2, 100, 'push(N, R, D), or perform(10, N, R, D): Delivers N units of resource R to drone D. N is required (1 for one unit). It takes one minute of game time. Burns 1 fuel.', -1, -1, 1, 0),
  (11, 'Pull resource', 2, 100, 'pull(N, R, D), or perform(11, N, R, D): Pulls N units of resource R from drone D. N is required (1 for one unit). It takes one minute of game time. Burns 1 fuel.', -1, -1, 1, 0),
  (12, 'Launch drone', 2, 100, 'launch(D, K), or perform(12, D, K): Builds a new drone (a clone) from ship kit K in the hold, beside this one, with drone D''s program and 20 of this drone''s fuel; it runs launched(). Takes 1 hour plus the light time from D. Burns 30 fuel.', 1, 1, 0, 0),
  (17, 'Post sell order (double price)', 3, 100, 'perform(17, P, M, R): Places order to sell resource R at price P (any whole number of credits), keeping min M units at drone''s cargo hold. Burns 1 fuel.', 1, 1, 0, 4),
  (18, 'Post buy order (double price)', 3, 100, 'perform(18, P, M, R): Places order to buy resource R at price P (any whole number of credits), keeping max M units at drone''s cargo hold. Burns 1 fuel.', 1, 1, 0, 4),
  (33, 'Station delivery', 0, 100, 'Goods a House station delivers or returns when a batch clears. Not performed by drones.', 1, 1, 0, 0),
  (34, 'Plunder wreck', 1, 100, 'plunder(W), or perform(34, W): Plunders the wreck W (a drone ID) where the drone is: after 1 hour the drone gets its share of the wreck''s goods and parts, as far as its hold has room; the rest is destroyed. A wreck is plundered once. Burns 1 fuel.', 1, 1, 0, 0),
  (35, 'Plunder haul', 0, 100, 'Goods and parts a plunderer takes from a wreck, and their loss from the wreck. Not performed by drones.', 1, 1, 0, 0),
  (40, 'Broadcast', 1, 100, 'broadcast(text), or perform(40, text): Broadcasts the text (1 to 80 printable characters) as an event, seen locally (query 803) and by the Earth database (804); its text: query 844. Burns 1 fuel.', 1, 1, 0, 0),
  (41, 'Post share sell order', 3, 100, 'sell_shares(company, keep, price), or perform(41, C, K, P): posts a sell order for company C''s shares at P credits each, selling while the drone''s company holds more than K (P 0 withdraws it), at the Earth exchange (it gets there at the speed of', 1, 1, 0, 0),
  (42, 'Post share buy order', 3, 100, 'buy_shares(company, want, price), or perform(42, C, W, P): posts a buy order for company C''s shares at P credits each, buying while the drone''s company holds fewer than W (P 0 withdraws it), at the Earth exchange (it gets there at the speed of', 1, 1, 0, 0),
  (43, 'Pull shares', 3, 100, 'pull_shares(n, company, seller), or perform(43, N, C, S): buys N of company C''s shares from company S''s sell order, at its price, at the Earth exchange (it gets there at the speed of light). Burns 1 fuel.', 1, 1, 0, 0),
  (44, 'Push shares', 3, 100, 'push_shares(n, company, buyer), or perform(44, N, C, B): sells N of company C''s shares into company B''s buy order, at its price, at the Earth exchange (it gets there at the speed of light). Burns 1 fuel.', 1, 1, 0, 0),
  (5001, 'Activate Engine I', 0, 100, 'travel(N), or perform(5001, N): Moves the spacecraft to the astronomical object whose Location ID is N. Burns 5 fuel.', 1, 1, 0, 0),
  (5911, 'Import resource', 2, 100, 'perform(5911, N, R): Brings N units of resource R up from the planet surface. House station drones only: it needs an Import Station, which players can never get. Takes 1 game second.', 1, 1, 0, 0),
  (5921, 'Export resource', 2, 100, 'perform(5921, N, R): Sends N units of resource R down to the planet surface. House station drones only: it needs an Export Station, which players can never get. Takes 1 game second.', 1, 1, 0, 0),
  (11000, 'Mine magmite', 0, 100, 'mine(magmite), or perform(11000): Mine magmite from the planet''s surface, if present. Uses a Slug (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11010, 'Mine formite', 0, 100, 'mine(1010), or perform(11010): Mine formite from a planet''s surface, if present. Uses a Slug (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11020, 'Mine voxite', 0, 100, 'mine(1020), or perform(11020): Mine voxite from the surface of a planet, if present. Uses a Slug (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11030, 'Mine zenolite', 0, 100, 'mine(1030), or perform(11030): Mine zenolite from a planet''s surface, if present. Uses a Slug (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11100, 'Mine kunspar', 0, 100, 'mine(kunspar), or perform(11100): Mine kunspar from the surface of a moon, if present. Uses a Worm (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11110, 'Mine yalspar', 0, 100, 'mine(yalspar), or perform(11110): Mine yalspar from the surface of a moon, if present. Uses a Worm (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11120, 'Mine vladnium', 0, 100, 'mine(vladnium), or perform(11120): Mine vladnium from the surface of a moon, if present. Uses a Worm (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11130, 'Mine wolfite', 0, 100, 'mine(wolfite), or perform(11130): Mine wolfite from the surface of a moon, if present. Uses a Worm (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11200, 'Mine kronite', 0, 100, 'mine(1200), or perform(11200): Mine kronite from an asteroid, if present. Uses a Crawler (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11210, 'Mine efrite', 0, 100, 'mine(1210), or perform(11210): Mine efrite from an asteroid, if present. Uses a Crawler (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11220, 'Mine olivium', 0, 100, 'mine(1220), or perform(11220): Mine olivium from an asteroid, if present. Uses a Crawler (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11230, 'Mine aladanite', 0, 100, 'mine(1230), or perform(11230): Mine aladanite from an asteroid, if present. Uses a Crawler (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11300, 'Mine halosite', 0, 100, 'mine(1300), or perform(11300): Mine halosite from a comet, if present. Uses a Crawler (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11310, 'Mine stellarite', 0, 100, 'mine(1310), or perform(11310): Mine stellarite from a comet, if present. Uses a Crawler (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11320, 'Mine mullinite', 0, 100, 'mine(1320), or perform(11320): Mine mullinite from a comet, if present. Uses a Crawler (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11330, 'Mine oznium', 0, 100, 'mine(1330), or perform(11330): Mine oznium from a comet, if present. Uses a Crawler (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11400, 'Mine tephnium', 0, 100, 'mine(1400), or perform(11400): Minetephnium from a planetary ring, if present. Uses a Crawler (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11410, 'Mine neptine', 0, 100, 'mine(1410), or perform(11410): Mine neptine from a planetary ring, if present. Uses a Crawler (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11420, 'Mine empirogen', 0, 100, 'mine(1420), or perform(11420): Mine empirogen from a planetary ring, if present. Uses a Crawler (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11430, 'Mine laudite', 0, 100, 'mine(1430), or perform(11430): Mine laudite from a planetary ring, if present. Uses a Crawler (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (12021, 'Make Alloys (A1)', 0, 100, 'make(alloys_a1), or perform(12021): Uses 2 Metals (A1) to make 1 Alloys (A1). Needs a Smelter (A1); takes 2 hours. Burns 2 fuel.', 1, 1, 0, 0),
  (12022, 'Make Alloys (A2)', 0, 100, 'make(alloys_a2), or perform(12022): Uses 1 Metals (A1), 1 Metals (A2) to make 1 Alloys (A2). Needs a Smelter (A1); takes 2 hours. Burns 2 fuel.', 1, 1, 0, 0),
  (12023, 'Make Alloys (A3)', 0, 100, 'make(alloys_a3), or perform(12023): Uses 1 Metals (A1), 1 Metals (A2), 1 Metals (A3) to make 2 Alloys (A3). Needs a Smelter (A1); takes 2 hours. Burns 2 fuel.', 1, 1, 0, 0),
  (12042, 'Make Organics (A2)', 0, 100, 'make(organics_a2), or perform(12042): Uses 1 Inorganics (A2), 2 Organics (A1) to make 2 Organics (A2). Needs a Chemical Reactor (A1); takes 2 hours. Burns 2 fuel.', 1, 1, 0, 0),
  (12043, 'Make Organics (A3)', 0, 100, 'make(2043), or perform(12043): Uses 1 Inorganics (A3), 2 Organics (A2) to make 2 Organics (A3). Needs a Chemical Reactor (A1); takes 2 hours. Burns 2 fuel.', 1, 1, 0, 0),
  (12051, 'Make Polymers (A1)', 0, 100, 'make(2051), or perform(12051): Uses 1 Inorganics (A1), 1 Organics (A1) to make 1 Polymers (A1). Needs a Chemical Reactor (A1); takes 2 hours. Burns 2 fuel.', 1, 1, 0, 0),
  (12052, 'Make Polymers (A2)', 0, 100, 'make(2052), or perform(12052): Uses 1 Inorganics (A1), 1 Organics (A1), 1 Organics (A2) to make 2 Polymers (A2). Needs a Chemical Reactor (A1); takes 2 hours. Burns 2 fuel.', 1, 1, 0, 0),
  (12053, 'Make Polymers (A3)', 0, 100, 'make(2053), or perform(12053): Uses 1 Inorganics (A1), 1 Organics (A2), 1 Organics (A3) to make 2 Polymers (A3). Needs a Chemical Reactor (A1); takes 2 hours. Burns 2 fuel.', 1, 1, 0, 0),
  (12061, 'Make Fuel (A1)', 0, 100, 'make(fuel), or perform(12061): Uses 1 Organics (A1), 2 Inorganics (A1) to make 30 Fuel (A1). Needs a Chemical Reactor (A1); takes 2 hours. Burns 2 fuel.', 1, 1, 0, 0),
  (13001, 'Make Sheets (A1)', 0, 100, 'make(3001), or perform(13001): Uses 2 Alloys (A1) to make 1 Sheets (A1). Needs a Smelter (A1); takes 4 hours. Burns 3 fuel.', 1, 1, 0, 0),
  (13011, 'Make Rods (A1)', 0, 100, 'make(rods), or perform(13011): Uses 1 Alloys (A1) to make 1 Rods (A1). Needs a Smelter (A1); takes 4 hours. Burns 3 fuel.', 1, 1, 0, 0),
  (13021, 'Make Cables (A1)', 0, 100, 'make(3021), or perform(13021): Uses 2 Alloys (A1) to make 1 Cables (A1). Needs a Smelter (A1); takes 4 hours. Burns 3 fuel.', 1, 1, 0, 0),
  (13031, 'Make Fasteners (A1)', 0, 100, 'make(3031), or perform(13031): Uses 2 Alloys (A2) to make 1 Fasteners (A1). Needs a Smelter (A1); takes 4 hours. Burns 3 fuel.', 1, 1, 0, 0),
  (13101, 'Make Springs (A1)', 0, 100, 'make(3101), or perform(13101): Uses 2 Alloys (A2) to make 1 Springs (A1). Needs a Smelter (A1); takes 4 hours. Burns 3 fuel.', 1, 1, 0, 0),
  (13111, 'Make Gears (A1)', 0, 100, 'make(3111), or perform(13111): Uses 2 Alloys (A1) to make 1 Gears (A1). Needs a Smelter (A1); takes 4 hours. Burns 3 fuel.', 1, 1, 0, 0),
  (13121, 'Make Pulleys (A1)', 0, 100, 'make(3121), or perform(13121): Uses 2 Alloys (A1) to make 1 Pulleys (A1). Needs a Smelter (A1); takes 4 hours. Burns 3 fuel.', 1, 1, 0, 0),
  (13141, 'Make Belts (A1)', 0, 100, 'make(3141), or perform(13141): Uses 2 Polymers (A1) to make 1 Belts (A1). Needs a Chemical Reactor (A1); takes 4 hours. Burns 3 fuel.', 1, 1, 0, 0),
  (13201, 'Make Conductors (A1)', 0, 100, 'make(3201), or perform(13201): Uses 2 Alloys (A1) to make 1 Conductors (A1). Needs a Smelter (A1); takes 4 hours. Burns 3 fuel.', 1, 1, 0, 0),
