INSERT INTO `queries` (id, name, description, parameters, script) VALUES
  (100, 'Get company name', 'company_name(N), or ask(100, N): Returns the name for company N.', 1, 'SELECT name FROM companies WHERE company_id = [value_1];'),
  (101, 'Get company credits', 'company_credits(N), or ask(101, N): Returns the number of credits in the company''s bank account were Company ID = N.', 1, 'SELECT credits AS d_credits FROM companies WHERE company_id = [value_1];'),
  (110, 'List company spacecraft', 'company_drones(N), or ask(110, N): Returns a list of the IDs for the spacecraft that are owned by company N.', 1, 'SELECT agent_id FROM agents WHERE company_id = [value_1] ORDER BY agent_id;'),
  (200, 'Get spacecraft name', 'drone_name(N), or ask(200, N): Returns the spacecraft name [30] for Spacraft ID N.', 1, 'SELECT agents.name FROM agents WHERE (((agents.agent_id)=[value_1]));'),
  (201, 'Get spacecraft owner', 'owner(N), or ask(201, N): Return the Company ID of the compony that owns Spacecraft ID N.', 1, 'SELECT company_id FROM agents WHERE agent_id = [value_1];'),
  (202, 'Get spaecraft location', 'where_is(N), or ask(202, N): Returns the location ID of spacecraft N.', 1, 'SELECT object_id FROM agents WHERE agent_id = [value_1];'),
  (203, 'Get spacecraft hull type', 'hull(N), or ask(203, N): Retuns the hull type of spacecraft N.', 1, 'SELECT hull_type FROM agents WHERE agent_id=[value_1];'),
  (204, 'Get cargo mass', 'cargo_mass(N), or ask(204, N): Returns the total cargo mass in kg of spacecraft N.', 1, 'SELECT IFNULL(SUM(i.units * r.mass), 0) FROM sqInventory AS i INNER JOIN resources AS r ON r.id = i.resource WHERE i.drone = [value_1];'),
  (205, 'Get my spacecraft ID', 'me(), or ask(205): Returns the spacecraft ID of the requesting spacecraft.', 0, 'SELECT agent_id FROM agents WHERE agent_id = [drone_id];'),
  (207, 'Game time now', 'now(), or ask(207): The game time now: the game day (day 0 is the world''s first) and the minutes into it (0 to 1,439).', 0, 'SELECT FLOOR(([game_now] - epoch) / 86400) AS day, FLOOR(MOD([game_now] - epoch, 86400) / 60) AS minute FROM game_clock WHERE id = 1;'),
  (210, 'List spacecraft inventory', 'hold(N), or ask(210, N): Lists the resources and quantities in the cargo hold of spacecraft N.', 1, 'SELECT resource, units FROM sqInventory WHERE drone = [value_1] AND units > 0 ORDER BY units DESC;'),
  (212, 'Get resource quantity', 'units(N), or ask(212, N): Returns how many units of resource N are in the requesting spacecraft''s cargo hold.', 1, 'SELECT (SELECT IFNULL(SUM(hd.units), 0) FROM holdings hd WHERE hd.drone = [drone_id] AND hd.resource = [value_1] AND hd.installed IN (0, 1) AND hd.locked IN (0, 1));'),
  (300, 'Get hull type name', 'hull_name(N), or ask(300, N): Returns the name of hull type N.', 1, 'SELECT name FROM hulls WHERE id=[value_1];'),
  (301, 'Get hull type cargo capacity', 'hull_capacity(N), or ask(301, N): Returns the cargo capacity in kg of hull type N.', 1, 'SELECT cargo_capacity FROM hulls WHERE id=[value_1];'),
  (400, 'Get resource name', 'resource_name(N), or ask(400, N): Retuns the name of resource N.', 1, 'SELECT name FROM resources WHERE id=[value_1];'),
  (401, 'Get resource unit mass', 'unit_mass(N), or ask(401, N): Retuns the unit mass in kg of resource N.', 1, 'SELECT mass FROM resources WHERE id=[value_1];'),
  (410, 'List best extraction sites', 'best_sites(N), or ask(410, N): Returns the top extraction sites and abundancies for the resource N.', 1, 'SELECT location, multiplier FROM abundancies WHERE resource=[value_1] ORDER BY multiplier DESC;'),
  (500, 'Get protocol name', 'protocol_name(N), or ask(500, N): Returns the name of protocol N.', 1, 'SELECT name FROM protocols WHERE id = [value_1];'),
  (501, 'Get protocol duration', 'protocol_minutes(N), or ask(501, N): Returns the duration in minutes of protocol N.', 1, 'SELECT MAX(time) FROM (SELECT time FROM resource_effects WHERE protocol = [value_1] UNION SELECT time FROM market_effects WHERE protocol = [value_1]) AS combined;'),
  (510, 'List consumed resources', 'consumes(N), or ask(510, N): Lists the resources and quantities that are consumed by protocol N.', 1, 'SELECT resource, quantity FROM resource_effects WHERE protocol=[value_1] AND deplete=1 AND locked=0 ORDER BY quantity DESC;'),
  (511, 'List produced resources', 'produces(N), or ask(511, N): Lists the resources and quantities that are produced by protocol N.', 1, 'SELECT resource, quantity FROM resource_effects WHERE protocol=[value_1] AND deplete=0 AND locked=0 ORDER BY quantity DESC;'),
  (512, 'List retained resources', 'retains(N), or ask(512, N): Lists the resources and quantities that are used by the protocol but returned when done.', 1, 'SELECT resource, quantity FROM resource_effects WHERE protocol=[value_1] AND deplete=0 AND locked=1 ORDER BY quantity DESC;'),
  (520, 'List consuming protocols', 'consumers(N), or ask(520, N): Lists all the protocols and qantities that deplete resource N.', 1, 'SELECT protocol, quantity FROM resource_effects WHERE resource = [value_1] AND deplete = 1 AND locked = 0 ORDER BY quantity DESC;'),
  (521, 'List producing protocols', 'producers(N), or ask(521, N): Lists all the procedures and quantities that produce resource N.', 1, 'SELECT protocol, quantity FROM resource_effects WHERE resource = [value_1] AND deplete = 0 AND locked = 0 ORDER BY quantity DESC;'),
  (522, 'List retaining protocols', 'users(N), or ask(522, N): Lists all the protocols and quatities that use resource N without consuming it.', 1, 'SELECT protocol, quantity FROM resource_effects WHERE resource = [value_1] AND deplete = 0 AND locked = 1 ORDER BY quantity DESC;'),
  (600, 'List local buy orders', 'buy_orders(N), or ask(600, N): Lists buy orders for resource N at the requesting spacecraft''s location: price, wanted maximum, units held, spacecraft ID.', 1, 'SELECT o.price AS d_price, o.quantity, o.units, o.drone FROM latest_orders AS o FORCE INDEX (latest_orders_here) WHERE o.resource = [value_1] AND o.event_type = 5 AND o.is_open = 1 AND (SELECT c.credits FROM companies AS c INNER JOIN agents AS b ON b.company_id = c.company_id WHERE b.agent_id = o.drone) >= o.price AND o.place = (SELECT object_id FROM agents WHERE agent_id = [drone_id]) AND NOT EXISTS (SELECT 1 FROM events AS m FORCE INDEX (events_pending) WHERE m.drone = o.drone AND m.event_type = 3 AND m.outcome = 0 AND m.game_t > [game_now]) ORDER BY o.price DESC, o.drone;'),
  (601, 'List buy orders here', 'ask(601, N): Lists buy orders for resource N where the drone is (like 600): price, wanted maximum, units held, spacecraft ID. Only where the drone is: for elsewhere, see the price board (680).', 1, 'SELECT o.price AS d_price, o.quantity, o.units, o.drone FROM latest_orders AS o FORCE INDEX (latest_orders_here) WHERE o.resource = [value_1] AND o.event_type = 5 AND o.is_open = 1 AND (SELECT c.credits FROM companies AS c INNER JOIN agents AS b ON b.company_id = c.company_id WHERE b.agent_id = o.drone) >= o.price AND o.place = (SELECT object_id FROM agents WHERE agent_id = [drone_id]) AND NOT EXISTS (SELECT 1 FROM events AS m FORCE INDEX (events_pending) WHERE m.drone = o.drone AND m.event_type = 3 AND m.outcome = 0 AND m.game_t > [game_now]) ORDER BY o.price DESC, o.drone;'),
  (610, 'List local sell orders', 'sell_orders(N), or ask(610, N): Lists sell orders for resource N at the requesting spacecraft''s location: price, kept minimum, units held, spacecraft ID.', 1, 'SELECT o.price AS d_price, o.quantity, o.units, o.drone FROM latest_orders AS o FORCE INDEX (latest_orders_here) WHERE o.resource = [value_1] AND o.event_type = 4 AND o.is_open = 1 AND o.place = (SELECT object_id FROM agents WHERE agent_id = [drone_id]) AND NOT EXISTS (SELECT 1 FROM events AS m FORCE INDEX (events_pending) WHERE m.drone = o.drone AND m.event_type = 3 AND m.outcome = 0 AND m.game_t > [game_now]) ORDER BY o.price ASC, o.drone;'),
  (611, 'List sell orders here', 'ask(611, N): Lists sell orders for resource N where the drone is (like 610): price, kept minimum, units held, spacecraft ID. Only where the drone is: for elsewhere, see the price board (680).', 1, 'SELECT o.price AS d_price, o.quantity, o.units, o.drone FROM latest_orders AS o FORCE INDEX (latest_orders_here) WHERE o.resource = [value_1] AND o.event_type = 4 AND o.is_open = 1 AND o.place = (SELECT object_id FROM agents WHERE agent_id = [drone_id]) AND NOT EXISTS (SELECT 1 FROM events AS m FORCE INDEX (events_pending) WHERE m.drone = o.drone AND m.event_type = 3 AND m.outcome = 0 AND m.game_t > [game_now]) ORDER BY o.price ASC, o.drone;'),
  (612, 'Sell orders here up to a price', 'ask(612, N, P): Sell orders for resource N where the drone is at a price of at most P, cheapest first: price, kept minimum, stock, drone.', 3, 'SELECT o.price AS d_price, o.quantity, o.units, o.drone FROM latest_orders AS o FORCE INDEX (latest_orders_here) WHERE o.resource = [value_3] AND o.event_type = 4 AND o.is_open = 1 AND o.place = (SELECT object_id FROM agents WHERE agent_id = [drone_id]) AND NOT EXISTS (SELECT 1 FROM events AS m FORCE INDEX (events_pending) WHERE m.drone = o.drone AND m.event_type = 3 AND m.outcome = 0 AND m.game_t > [game_now]) AND o.price <= [dvalue_1] ORDER BY o.price ASC, o.drone;'),
  (615, 'Orders everywhere', 'orders_everywhere(N), or ask(615, N): Every exchange''s orders for resource N: live where the drone is, an hour old elsewhere. Rows: place, side (1 buy, 2 sell), price, units on offer or wanted, drone, hours old.', 1, 'WITH a AS (SELECT g.agent_id, g.object_id, g.company_id, g.arrived_t, IF(g.object_id = (SELECT object_id FROM agents WHERE agent_id = [drone_id]), [game_now], [game_now] - 3600) AS t FROM agents g WHERE g.wrecked_at IS NULL AND NOT EXISTS (SELECT 1 FROM events AS m FORCE INDEX (events_pending) WHERE m.drone = g.agent_id AND m.event_type = 3 AND m.outcome = 0 AND m.game_t > [game_now])), l AS (SELECT e.drone, MAX(e.id) AS id FROM events e INNER JOIN a ON a.agent_id = e.drone WHERE e.outcome = 1 AND e.event_type IN (4, 5) AND e.resource = [value_1] AND e.game_t <= a.t GROUP BY e.drone, e.event_type) SELECT a.object_id AS place, IF(o.event_type = 5, 1, 2) AS side, o.new_credits AS price, ABS(i.units - o.new_quantity) AS units, o.drone, IF(a.t = [game_now], 0, 1) AS hours_old FROM l INNER JOIN events o ON o.id = l.id INNER JOIN a ON a.agent_id = l.drone JOIN LATERAL (SELECT (SELECT IFNULL(SUM((SELECT h.new_quantity FROM events h WHERE h.id = GREATEST(IFNULL((SELECT x.id FROM events x FORCE INDEX (events_inventory) WHERE x.drone = a.agent_id AND x.resource = [value_1] AND x.installed = k.i AND x.locked = k.l AND x.outcome = 1 AND x.event_type = 1 AND x.game_t <= a.t ORDER BY x.id DESC LIMIT 1), 0), IFNULL((SELECT x.id FROM events x FORCE INDEX (events_inventory) WHERE x.drone = a.agent_id AND x.resource = [value_1] AND x.installed = k.i AND x.locked = k.l AND x.outcome = 1 AND x.event_type = 2 AND x.game_t <= a.t ORDER BY x.id DESC LIMIT 1), 0)))), 0) FROM (SELECT 0 i, 0 l UNION ALL SELECT 0, 1 UNION ALL SELECT 1, 0 UNION ALL SELECT 1, 1) k) AS units) i WHERE IFNULL(a.arrived_t, 0) <= a.t AND IF(o.event_type = 4, i.units > o.new_quantity, i.units < o.new_quantity AND (SELECT c.credits FROM companies c WHERE c.company_id = a.company_id) >= o.new_credits) ORDER BY place, side, price;'),
  (620, 'Local market volume', 'volume_here(N, H), or ask(620, N, H): Units of resource N traded at the requesting spacecraft''s location in the last H game hours, credits paid for them, and number of trades.', 2, 'SELECT IFNULL(SUM(units),0) AS d_units, IFNULL(SUM(credits),0) AS d_credits, COUNT(*) FROM trades WHERE resource=[value_2] AND [game_now]-game_t<=[value_1]*3600 AND location=(SELECT object_id FROM agents WHERE agent_id = [drone_id]);'),
  (621, 'Solar market volume, an hour old', 'volume_everywhere(N, H), or ask(621, N, H): Units of resource N traded anywhere in the solar system in the H game hours up to one game hour ago, credits paid for them, and number of trades.', 2, 'SELECT IFNULL(SUM(units),0) AS d_units, IFNULL(SUM(credits),0) AS d_credits, COUNT(*) FROM trades WHERE resource=[value_2] AND game_t<=[game_now]-3600 AND [game_now]-3600-game_t<=[value_1]*3600;'),
  (630, 'Station goods', 'ask(630): House station drones only: what the exchange where the drone is trades now: resource, side (1: it buys, 2: it sells), listed price, daily units, units held.', 0, 'SELECT g.resource, g.side, g.price AS d_price, g.daily_units, IFNULL((SELECT MAX((SELECT IFNULL(SUM(hd.units), 0) FROM holdings hd WHERE hd.drone = a.agent_id AND hd.resource = g.resource AND hd.installed IN (0, 1) AND hd.locked IN (0, 1))) FROM agents a WHERE a.station_id = g.station_id), 0) AS d_units FROM house_market g WHERE g.station_id IN (SELECT id FROM stations WHERE object_id = (SELECT object_id FROM agents WHERE agent_id = [drone_id])) AND g.from_day <= FLOOR(([game_now] - (SELECT epoch FROM game_clock WHERE id = 1)) / 86400) AND EXISTS (SELECT 1 FROM agents WHERE agent_id = [drone_id] AND station_id IS NOT NULL) ORDER BY g.resource, g.side;'),
  (640, 'Deposits here', 'deposits(), or ask(640): The mining deposits where the drone is: resource, units left now, capacity, units regained per game day. A mined-out deposit yields nothing until it refills.', 0, 'SELECT d.resource, FLOOR(LEAST(d.capacity, IFNULL(s.amount, d.capacity) + d.refill_per_day * ([game_now] - IFNULL(s.refilled_t, [game_now])) / 86400)) AS d_units, d.capacity AS d_capacity, d.refill_per_day FROM deposits d LEFT JOIN deposit_state s ON s.object_id = d.object_id AND s.resource = d.resource WHERE d.object_id = (SELECT object_id FROM agents WHERE agent_id = [drone_id]) ORDER BY d.resource;'),
  (650, 'My taxes', 'taxes(), or ask(650): The sales tax: the share of each sale the seller pays, in thousandths (50 is 5%); what the drone''s company paid in the last game day, and in all.', 0, 'SELECT h.sales_tax_permille, (SELECT IFNULL(SUM(t.amount), 0) FROM company_taxes t WHERE t.company_id = c.company_id AND t.eliminated = 0 AND t.charged_t > [game_now] - 86400) AS d_day, (SELECT IFNULL(SUM(t.amount), 0) FROM company_taxes t WHERE t.company_id = c.company_id AND t.eliminated = 0) AS d_all FROM companies c JOIN house_rules h ON h.id = 1 WHERE c.company_id = (SELECT company_id FROM agents WHERE agent_id = [drone_id]);'),
  (655, 'My company''s trades', 'earnings(H), or ask(655, H): The drone''s company''s trades over the last H game hours, by resource: credits from sales, units sold, sales tax paid, credits paid for purchases, units bought.', 1, 'SELECT t.resource, SUM(IF(s.company_id = (SELECT company_id FROM agents WHERE agent_id = [drone_id]), t.credits, 0)) AS sales, SUM(IF(s.company_id = (SELECT company_id FROM agents WHERE agent_id = [drone_id]), t.units, 0)) AS sold, SUM(IF(s.company_id = (SELECT company_id FROM agents WHERE agent_id = [drone_id]), t.tax, 0)) AS tax, SUM(IF(b.company_id = (SELECT company_id FROM agents WHERE agent_id = [drone_id]), t.credits, 0)) AS purchases, SUM(IF(b.company_id = (SELECT company_id FROM agents WHERE agent_id = [drone_id]), t.units, 0)) AS bought FROM trades AS t INNER JOIN agents AS s ON s.agent_id = t.seller INNER JOIN agents AS b ON b.agent_id = t.buyer WHERE t.game_t > [game_now] - [value_1] * 3600 AND t.game_t <= [game_now] AND (s.company_id = (SELECT company_id FROM agents WHERE agent_id = [drone_id]) OR b.company_id = (SELECT company_id FROM agents WHERE agent_id = [drone_id])) GROUP BY t.resource ORDER BY t.resource;'),
  (660, 'Wrecks here', 'wrecks(), or ask(660): The wrecks where the drone is: drone ID, 1 if it has been plundered (else 0).', 0, 'SELECT agent_id, plundered_at IS NOT NULL FROM agents WHERE wrecked_at IS NOT NULL AND object_id = (SELECT object_id FROM agents WHERE agent_id = [drone_id]) AND agent_id <> [drone_id] ORDER BY agent_id;'),
  (661, 'Wreck hold', 'wreck_hold(W), or ask(661, W): What is aboard the wreck W where the drone is: resource, units.', 1, 'SELECT i.resource, i.units FROM sqInventory i JOIN agents w ON w.agent_id = i.drone WHERE i.drone = [value_1] AND w.wrecked_at IS NOT NULL AND w.object_id = (SELECT object_id FROM agents WHERE agent_id = [drone_id]) AND i.units > 0 ORDER BY i.resource;'),
  (670, 'My clones', 'my_clones(), or ask(670): The drones this drone launched, oldest first: drone ID, 1 if it is a wreck (else 0).', 0, 'SELECT agent_id, wrecked_at IS NOT NULL FROM agents WHERE parent_id = [drone_id] ORDER BY agent_id;'),
  (671, 'My lineage', 'lineage(), or ask(671): The drone that launched this one (0 if none), and its generation (0 for a drone released or registered, 1 for its clones, and so on).', 0, 'SELECT IFNULL(parent_id, 0), generation FROM agents WHERE agent_id = [drone_id];'),
  (680, 'Price board', 'price_board(N), or ask(680, N): The public price board for resource N: for each place where it traded in the game day up to one game hour ago, the place, units, credits paid and trades.', 1, 'SELECT location, IFNULL(SUM(units),0) AS d_units, IFNULL(SUM(credits),0) AS d_credits, COUNT(*) FROM trades WHERE resource=[value_1] AND location IS NOT NULL AND game_t<=[game_now]-3600 AND game_t>[game_now]-3600-86400 GROUP BY location ORDER BY location;'),
  (682, 'Sales on a day', 'sales(N, D), or ask(682, N, D): How much of resource N sold on the game day D days ago (0: today so far), an hour old, for each place: the place, units sold, average price.', 2, 'SELECT t.location, SUM(t.units) AS d_units, ROUND(SUM(t.credits) / SUM(t.units)) AS price FROM trades t WHERE t.resource = [value_2] AND t.location IS NOT NULL AND t.game_t >= ((SELECT epoch FROM game_clock WHERE id = 1) + (FLOOR(([game_now] - (SELECT epoch FROM game_clock WHERE id = 1)) / 86400) - [value_1]) * 86400) AND t.game_t < ((SELECT epoch FROM game_clock WHERE id = 1) + (FLOOR(([game_now] - (SELECT epoch FROM game_clock WHERE id = 1)) / 86400) - [value_1]) * 86400) + 86400 AND t.game_t <= [game_now] - 3600 GROUP BY t.location ORDER BY t.location;'),
  (690, 'Share sell orders', 'Sell orders for company N''s shares at the Earth exchange, cheapest first: price, kept minimum, shares held, company.', 1, 'SELECT o.price AS d_price, o.limit_units, IFNULL(s.units, 0), o.company FROM share_orders AS o INNER JOIN companies AS c ON c.company_id = o.company AND c.eliminated_at IS NULL LEFT JOIN shares AS s ON s.company = o.share_company AND s.holder = o.company WHERE o.share_company = [value_1] AND o.side = 1 AND IFNULL(s.units, 0) > o.limit_units ORDER BY o.price ASC, o.company;'),
  (691, 'Share buy orders', 'Buy orders for company N''s shares at the Earth exchange, highest first: price, wanted maximum, shares held, company.', 1, 'SELECT o.price AS d_price, o.limit_units, IFNULL(s.units, 0), o.company FROM share_orders AS o INNER JOIN companies AS c ON c.company_id = o.company AND c.eliminated_at IS NULL LEFT JOIN shares AS s ON s.company = o.share_company AND s.holder = o.company WHERE o.share_company = [value_1] AND o.side = 2 AND IFNULL(s.units, 0) < o.limit_units AND c.credits >= o.price ORDER BY o.price DESC, o.company;'),
  (692, 'My shares', 'The shares the drone''s company holds, its own included: company, shares, the dividends they have paid it, the last trade price (0 if never traded).', 0, 'SELECT s.company, s.units, s.dividends AS d_dividends, IFNULL((SELECT t.price FROM share_trades AS t WHERE t.share_company = s.company ORDER BY t.id DESC LIMIT 1), 0) AS d_price FROM shares AS s WHERE s.holder = (SELECT company_id FROM agents WHERE agent_id = [drone_id]) AND s.units > 0 ORDER BY s.company;'),
  (693, 'Shareholders', 'Who holds company N''s shares, most first: company, shares.', 1, 'SELECT holder, units FROM shares WHERE company = [value_1] AND units > 0 ORDER BY units DESC, holder;'),
  (694, 'Share trades', 'Company N''s last 20 share trades, newest first: price, shares, seller, buyer, game day.', 1, 'SELECT t.price AS d_price, t.units, t.seller, t.buyer, FLOOR((t.game_t - g.epoch) / 86400) FROM share_trades AS t JOIN game_clock AS g ON g.id = 1 WHERE t.share_company = [value_1] ORDER BY t.id DESC LIMIT 20;'),
  (695, 'Recipe', 'recipe(R), or ask(695): The first recipe that makes resource R: protocol, resource, units (made: positive; used, fuel too: negative; the tool it needs: 0), minutes it takes. One row a resource, what it makes first.', 1, 'SELECT e.protocol, e.resource, SUM(IF(e.event_type = 1, e.quantity, -e.quantity)) AS units, (SELECT MAX(t.time) FROM resource_effects t WHERE t.protocol = e.protocol) DIV 60 AS minutes FROM resource_effects e WHERE e.installed = 0 AND e.local = 1 AND e.event_type IN (1, 2) AND e.protocol = (SELECT MIN(m.protocol) FROM resource_effects m WHERE m.resource = [value_1] AND m.event_type = 1 AND m.locked = 0 AND m.installed = 0 AND m.local = 1 AND (SELECT SUM(IF(d.event_type = 1, d.quantity, -d.quantity)) FROM resource_effects d WHERE d.protocol = m.protocol AND d.resource = m.resource AND d.installed = 0 AND d.local = 1 AND d.event_type IN (1, 2)) > 0 AND EXISTS (SELECT 1 FROM resource_effects u WHERE u.protocol = m.protocol AND u.event_type = 2 AND u.deplete = 1 AND u.locked = 0 AND u.resource NOT IN (m.resource, 2061))) GROUP BY e.protocol, e.resource HAVING units <> 0 OR MAX(e.locked) = 1 ORDER BY units DESC, e.resource;'),
  (700, 'Get location name', 'place_name(N), or ask(700, N): Returns the name of location ID N.', 1, 'SELECT object_name FROM objects WHERE object_id=[value_1];'),
  (701, 'Get location type', 'place_type(N), or ask(701, N): Returns the location type of location N.', 1, 'SELECT object_type FROM objects WHERE object_id=[value_1];'),
  (702, 'Get central body', 'orbits(N), or ask(702, N): Retuns the location ID for the body around which N is orbiting.', 1, 'SELECT central_body_object_id FROM objects WHERE object_id=[value_1];'),
  (703, 'Get location coordinates', 'position(N), or ask(703, N): Where location N is now: x, y and z from the Sun, in thousands of km. Updated every few game hours.', 1, 'SELECT ROUND(x_coord/1000) AS d_x, ROUND(y_coord/1000) AS d_y, ROUND(z_coord/1000) AS d_z FROM objects WHERE object_id=[value_1] AND x_coord IS NOT NULL;'),
  (704, 'Trip from here', 'trip_to(P), or ask(704, P): A trip from where the drone is to location P: the distance in thousands of km, the trip time in game seconds and in game hours, rounded up.', 1, 'SELECT ROUND(SQRT(POW(a.x_coord-b.x_coord,2)+POW(a.y_coord-b.y_coord,2)+POW(a.z_coord-b.z_coord,2))/1000) AS d_thousand_km, ROUND(GREATEST(1, 2*SQRT(SQRT(POW(a.x_coord-b.x_coord,2)+POW(a.y_coord-b.y_coord,2)+POW(a.z_coord-b.z_coord,2))*1000/(SELECT travel_acceleration FROM game_clock WHERE id = 1)))) AS d_seconds, CEIL(GREATEST(1, 2*SQRT(SQRT(POW(a.x_coord-b.x_coord,2)+POW(a.y_coord-b.y_coord,2)+POW(a.z_coord-b.z_coord,2))*1000/(SELECT travel_acceleration FROM game_clock WHERE id = 1)))/3600) AS hours FROM objects a, objects b WHERE a.x_coord IS NOT NULL AND b.x_coord IS NOT NULL AND a.object_id=(SELECT object_id FROM agents WHERE agent_id = [drone_id]) AND b.object_id=[value_1];'),
  (705, 'Trip between places', 'trip_between(A, B), or ask(705, A, B): A trip from location A to location B: the distance in thousands of km, the trip time in game seconds and in game hours, rounded up.', 2, 'SELECT ROUND(SQRT(POW(a.x_coord-b.x_coord,2)+POW(a.y_coord-b.y_coord,2)+POW(a.z_coord-b.z_coord,2))/1000) AS d_thousand_km, ROUND(GREATEST(1, 2*SQRT(SQRT(POW(a.x_coord-b.x_coord,2)+POW(a.y_coord-b.y_coord,2)+POW(a.z_coord-b.z_coord,2))*1000/(SELECT travel_acceleration FROM game_clock WHERE id = 1)))) AS d_seconds, CEIL(GREATEST(1, 2*SQRT(SQRT(POW(a.x_coord-b.x_coord,2)+POW(a.y_coord-b.y_coord,2)+POW(a.z_coord-b.z_coord,2))*1000/(SELECT travel_acceleration FROM game_clock WHERE id = 1)))/3600) AS hours FROM objects a, objects b WHERE a.x_coord IS NOT NULL AND b.x_coord IS NOT NULL AND a.object_id=[value_2] AND b.object_id=[value_1];'),
  (710, 'List orbiting bodies', 'orbiting(N), or ask(710, N): Returns a list of the object IDs that are in orbit around object N.', 1, 'SELECT object_id FROM objects WHERE central_body_object_id=[value_1];'),
  (720, 'List local spacecraft', 'drones_at(N), or ask(720, N): Lists all the drones at location N.', 1, 'SELECT agent_id FROM agents WHERE object_id =[value_1]'),
  (721, 'Drones at a place', 'crowd(P), or ask(721, P): How many drones are at location P now: working drones, wrecks.', 1, 'SELECT IFNULL(SUM(wrecked_at IS NULL),0), IFNULL(SUM(wrecked_at IS NOT NULL),0) FROM agents WHERE object_id = [value_1];'),
  (730, 'List local resources', 'minerals(N), or ask(730, N): Returns the resource ID and abundancy value of each resource that can be recovered from the location.', 1, 'SELECT resource, multiplier FROM abundancies WHERE location=[value_1] ORDER BY multiplier DESC;'),
  (800, 'List personal events', 'events_affecting(N), or ask(800, N): Lists the most recent events that affected spacecraft N.', 1, 'SELECT id AS d_id FROM events WHERE outcome = 1 AND drone = [value_1] ORDER BY game_t DESC, id DESC;'),
  (801, 'List local events', 'local_events(), or ask(801): Lists the most recent events at the requesting spacecraft''s location.', 0, 'SELECT e.id AS d_id FROM events AS e INNER JOIN agents AS a ON a.agent_id = e.drone WHERE e.outcome = 1 AND a.object_id = (SELECT object_id FROM agents WHERE agent_id = [drone_id]) ORDER BY e.game_t DESC, e.id DESC;'),
  (802, 'List solar events', 'ask(802): Lists the most recent events anywhere in the solar system.', 0, 'SELECT id AS d_id FROM events WHERE outcome = 1 ORDER BY game_t DESC, id DESC;'),
  (803, 'Search observed events', 'events_here(T), or ask(803, A, P, T, M, D, N, X, K, O): Lists the events this spacecraft has observed, newest first, that match A P T M D N X K O (see the manual); -1 means any.', 9, 'SELECT e.id AS d_id FROM events e LEFT JOIN actions a ON a.id=e.action LEFT JOIN agents g ON g.agent_id=e.drone WHERE e.outcome=1 AND (EXISTS(SELECT 1 FROM observations o WHERE o.event=e.id AND o.drone=[drone_id] AND o.game_t<=[game_now]) OR EXISTS(SELECT 1 FROM agents me WHERE me.agent_id=[drone_id] AND e.place=me.object_id AND e.game_t>=me.arrived_t AND e.game_t<=[game_now])) AND ([value_9]<0 OR a.drone=[value_9]) AND ([value_8]<0 OR a.protocol=[value_8]) AND ([value_7]<0 OR e.event_type=[value_7]) AND ([value_6]<0 OR [game_now]-e.game_t>=[value_6]*60) AND ([value_5]<0 OR e.drone=[value_5]) AND ([value_4]<0 OR e.resource=[value_4]) AND ([value_3]<0 OR (e.event_type=2)=([value_3]<>0)) AND ([value_2]<0 OR e.locked=([value_2]<>0)) AND ([value_1]<0 OR g.object_id=[value_1]) AND (e.event_type<>13 OR EXISTS(SELECT 1 FROM broadcasts b WHERE b.action_id=e.action AND b.company_id=(SELECT company_id FROM agents WHERE agent_id=[drone_id]))) ORDER BY e.game_t DESC,e.id DESC;'),
  (804, 'Search Earth database', 'events_earth(T), or ask(804, A, P, T, M, D, N, X, K, O): Lists the events reported to the Earth database that this spacecraft can know of (light from Earth has reached it), newest first, filtered like 803.', 9, 'SELECT e.id AS d_id FROM events e LEFT JOIN actions a ON a.id=e.action LEFT JOIN agents g ON g.agent_id=e.drone WHERE e.outcome=1 AND EXISTS(SELECT 1 FROM observations o WHERE o.event=e.id AND o.drone=0 AND o.game_t+(SELECT IFNULL(SQRT(POW(x.x_coord-h.x_coord,2)+POW(x.y_coord-h.y_coord,2)+POW(x.z_coord-h.z_coord,2))/299792.458,0) FROM objects x, objects h WHERE x.object_id=3 AND h.object_id=(SELECT object_id FROM agents WHERE agent_id=[drone_id]))<=[game_now]) AND ([value_9]<0 OR a.drone=[value_9]) AND ([value_8]<0 OR a.protocol=[value_8]) AND ([value_7]<0 OR e.event_type=[value_7]) AND ([value_6]<0 OR [game_now]-e.game_t>=[value_6]*60) AND ([value_5]<0 OR e.drone=[value_5]) AND ([value_4]<0 OR e.resource=[value_4]) AND ([value_3]<0 OR (e.event_type=2)=([value_3]<>0)) AND ([value_2]<0 OR e.locked=([value_2]<>0)) AND ([value_1]<0 OR g.object_id=[value_1]) AND (e.event_type<>13 OR EXISTS(SELECT 1 FROM broadcasts b WHERE b.action_id=e.action AND b.company_id=(SELECT company_id FROM agents WHERE agent_id=[drone_id]))) ORDER BY e.game_t DESC,e.id DESC;'),
  (810, 'Get event type', 'ask(810, N): Get the type ID for event N. N is an event ID, from an event list (800-804).', 2, 'SELECT event_type FROM events WHERE outcome=1 AND id=[dvalue_1];'),
  (811, 'Get event type name', 'ask(811, N): Returns the name of the type of event N. N is an event ID, from an event list (800-804).', 2, 'SELECT t.name FROM events AS e INNER JOIN event_types AS t ON t.id = e.event_type WHERE e.outcome = 1 AND e.id = [dvalue_1];'),
  (820, 'Get acting spacecraft', 'event_drone(N), or ask(820, N): Returns the ID of the spacecraft whose action caused event N. N is an event ID, from an event list (800-804).', 2, 'SELECT a.drone FROM events AS e INNER JOIN actions AS a ON a.id = e.action WHERE e.outcome = 1 AND e.id = [dvalue_1];'),
  (821, 'Get associated protocol', 'ask(821, N): Returns the ID of the protocol whose action caused event N. N is an event ID, from an event list (800-804).', 2, 'SELECT a.protocol FROM events AS e INNER JOIN actions AS a ON a.id = e.action WHERE e.outcome = 1 AND e.id = [dvalue_1];'),
  (831, 'Get affected spacecraft', 'ask(831, N): Return the ID of the spacecraft affected by event N. N is an event ID, from an event list (800-804).', 2, 'SELECT drone FROM events WHERE outcome=1 AND id=[dvalue_1];'),
  (832, 'Get affected resource', 'ask(832, N): Returns the ID of the resource affected by event N. N is an event ID, from an event list (800-804).', 2, 'SELECT resource FROM events WHERE outcome = 1 AND id = [dvalue_1];'),
  (840, 'Get new quantity', 'ask(840, N): Returns the new quantity set by event N. N is an event ID, from an event list (800-804).', 2, 'SELECT new_quantity FROM events WHERE outcome = 1 AND id = [dvalue_1];'),
  (841, 'Get new credits', 'ask(841, N): Returns the new credits set by event N. N is an event ID, from an event list (800-804).', 2, 'SELECT new_credits AS d_credits FROM events WHERE outcome = 1 AND id = [dvalue_1];'),
  (842, 'Get new location', 'ask(842, N): Returns the new location set by event N. N is an event ID, from an event list (800-804).', 2, 'SELECT new_location FROM events WHERE outcome = 1 AND id = [dvalue_1];'),
  (843, 'Get event time', 'ask(843, N): Returns when event N happened: its game day (day 0 is the world''s first) and the even seconds into that day. N is an event ID, from an event list (800-804).', 2, 'SELECT FROM_UNIXTIME(game_t) FROM events WHERE outcome = 1 AND id = [dvalue_1];'),
  (844, 'Get event message', 'message(N), or ask(844, N): The message of event N, a broadcast (event type 13) from a drone of this drone''s company; no row for other events or other companies'' messages. N is an event ID, from an event list (800-804).', 2, 'SELECT b.body FROM broadcasts b INNER JOIN events e ON e.action = b.action_id WHERE e.id = [dvalue_1] AND e.event_type = 13 AND b.company_id = (SELECT company_id FROM agents WHERE agent_id=[drone_id]);'),
  (845, 'Event details', 'event(N), or ask(845, N): Event N in one row: type, type name, acting drone, protocol, affected drone, resource, new quantity, new credits, new location, place, game day, seconds into it, message (your company''s only).', 1, 'SELECT e.event_type AS type, t.name AS type_name, IFNULL(x.drone, 0) AS acting, IFNULL(x.protocol, 0) AS protocol, e.drone AS affected, e.resource, e.new_quantity AS quantity, e.new_credits AS credits, e.new_location AS location, e.place, FLOOR((e.game_t - g.epoch) / 86400) AS day, MOD(e.game_t - g.epoch, 86400) AS seconds, (SELECT b.body FROM broadcasts AS b WHERE b.action_id = e.action AND e.event_type = 13 AND b.company_id = (SELECT company_id FROM agents WHERE agent_id=[drone_id]) LIMIT 1) AS message FROM events AS e INNER JOIN event_types AS t ON t.id = e.event_type LEFT JOIN actions AS x ON x.id = e.action INNER JOIN game_clock AS g ON g.id = 1 WHERE e.outcome = 1 AND e.id = [value_1];');
